import "./test-guard";
import assert from "node:assert/strict";
import { wikiGraph } from "../lib/wiki-graph";

// Text adapted from a real repo wiki: a map page, two topic pages, the generated index and lessons.
const files = {
  ".sstack/config.toml": "workflow = 'default'\n",
  ".sstack/wiki/index.md": [
    "# Wiki index",
    "",
    "<!-- generated by sstack-wiki index from page summaries; edit the pages, not this file -->",
    "",
    "- [job-lifecycle](job-lifecycle.md) — How a Linear issue becomes a job (and a PR) [stale]",
    "- [live-updates](live-updates.md) — pg NOTIFY hive_changes drives panel SSE refreshes",
    "- [start-here](start-here.md) — Map of hive's moving parts [stale] and which page to open",
    "",
  ].join("\n"),
  ".sstack/wiki/lessons.md": "- Run bun install first. See [start-here](start-here.md).\n",
  ".sstack/wiki/start-here.md": [
    "---",
    "summary: Map of hive's moving parts and which page to open",
    "updated: 3588135",
    "---",
    "",
    "| Task touches | Open |",
    "|---|---|",
    "| Pickup, claim, stages | [job-lifecycle](job-lifecycle.md) |",
    "| Why a page refreshes | [live-updates](./live-updates.md#notify) |",
    "| Again | [live-updates](live-updates.md) |",
    "",
    "Product overview: [product.md](../product.md). Rules: [lessons](lessons.md), [index](index.md), [me](start-here.md).",
    "Missing: [testing](testing.md). Elsewhere: [docs](https://example.com/x.md), [top](#top), [global](~/.sstack/wiki/x.md).",
  ].join("\n"),
  ".sstack/wiki/job-lifecycle.md":
    "---\nsummary: How a Linear issue becomes a job\n---\n\nRefreshes: [live-updates](live-updates.md).\n\n```md\n[fenced](start-here.md)\n```\n\nNot a link: `[span](start-here.md)`.\n",
  ".sstack/wiki/live-updates.md": "No frontmatter. Back to [start](start-here.md?x=1).\r\n",
};

const graph = wikiGraph(files);

// three nodes, sorted; index.md and lessons.md are not nodes
assert.deepEqual(
  graph.nodes.map((n) => n.name),
  ["job-lifecycle", "live-updates", "start-here"],
);
assert.equal(graph.nodes[2].summary, "Map of hive's moving parts and which page to open");
assert.equal(graph.nodes[1].summary, "", "a page without frontmatter has no summary");
assert.equal(graph.nodes[0].text, files[".sstack/wiki/job-lifecycle.md"], "a node carries its page text");

// edges: relative links between pages, deduplicated, fragments and queries stripped; code, URLs, self, index and lessons don't count
assert.deepEqual(graph.edges, [
  ["job-lifecycle", "live-updates"],
  ["live-updates", "start-here"],
  ["start-here", "job-lifecycle"],
  ["start-here", "live-updates"],
]);

// stale comes from the committed index's trailing marker, not from a `[stale]` mid-line
assert.deepEqual(
  graph.nodes.filter((n) => n.stale).map((n) => n.name),
  ["job-lifecycle"],
);

// a link to a missing wiki page is broken, not an edge; links out of the wiki are neither
assert.deepEqual(graph.broken, [{ from: "start-here", target: "testing.md" }]);

// no wiki: no nodes
assert.deepEqual(wikiGraph({ ".sstack/config.toml": "" }), { nodes: [], edges: [], broken: [] });

console.log("wiki-graph regressions passed");
